// render/art/packs/grade.ts — the post stack's colour-grade LUTs (wap-9): one per
// time-of-day keyframe, generated by `client/art-src/generate_luts.py`.
import type { ArtRow } from '../registry';

const GENERATOR = 'client/art-src/generate_luts.py';

/** The time-of-day keyframes the post stack can grade to. */
export type GradeKeyframe = 'day' | 'dusk' | 'night';

export const GRADE_KEYFRAMES: readonly GradeKeyframe[] = ['day', 'dusk', 'night'];

/** The keyframe the live game renders (a time-of-day cycle is backlog). */
export const LIVE_KEYFRAME: GradeKeyframe = 'day';

/** Lattice points per colour axis; a LUT strip is `LUT_SIZE²` wide and `LUT_SIZE` tall. */
export const LUT_SIZE = 32;

/** Each keyframe's LUT, relative to `client/public/assets/`. */
export const LUT_FILE: Readonly<Record<GradeKeyframe, string>> = {
  day: 'lut-day.png',
  dusk: 'lut-dusk.png',
  night: 'lut-night.png',
};

export const GRADE_PACK: readonly ArtRow[] = GRADE_KEYFRAMES.map(
  (keyframe): ArtRow => ({
    key: `grade/lut_${keyframe}`,
    file: LUT_FILE[keyframe],
    kind: 'lut',
    sheet: { w: LUT_SIZE * LUT_SIZE, h: LUT_SIZE },
    scale: 1,
    source: GENERATOR,
    provenance: 'placeholder-procedural',
    license: 'project-original',
  }),
);
